def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the uniform divider and take the panel following it.
    for r in range(h):
        if len(set(grid[r])) == 1:
            panel = grid[r + 1:]
            counts = {}
            for row in panel:
                for value in row:
                    counts[value] = counts.get(value, 0) + 1
            background = max(counts, key=counts.get)
            return [[3 if value != background else background for value in row]
                    for row in panel]

    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1:
            panel = [row[c + 1:] for row in grid]
            counts = {}
            for row in panel:
                for value in row:
                    counts[value] = counts.get(value, 0) + 1
            background = max(counts, key=counts.get)
            return [[3 if value != background else background for value in row]
                    for row in panel]

